var controlloContestualeNumericoContainer = ' \
<script type="text/x-handlebars-template"> \
    <div data-custom-field="true" data-custom-field-height="200"> \
        {{#container}}{{/container}} \
    </div> \
</script>';

var controlloContestualeNumericoContainerObject = ' \
<script type="text/x-handlebars-template"> \
    <div data-disable-interaction-custom-field="true"> \
        <div class="row"> \
            <div class="col-md-12">{{#with items.[0]}}{{#item}}{{/item}}{{/with}}</div> \
        </div> \
    </div> \
</script>';

(function($) {

    var Alpaca = $.alpaca;

    var isControlloContestualeValid = true;
    var templateErrore = "<p style='color:red;'><i class='glyphicon glyphicon-exclamation-sign'></i>&nbsp;%errorMessage%</p>";
    var templateWarning = "<p style='color:#737373;'><i class='glyphicon glyphicon-exclamation-sign'></i>&nbsp;%errorMessage%</p>";

    /**
     * Valida il campo valoreNumerico tramite chiamata AJAX
     * a verificaRequisitoContestualeUrl.
     * Mostra errori/warning in un div iniettato dinamicamente sotto il campo.
     */
    function validaControlloContestuale(campo, value) {
        if (typeof verificaRequisitoContestualeUrl === 'undefined' || !verificaRequisitoContestualeUrl) return;

        var form = $('.alpaca-form').alpaca('get');
        var erroreDiv = $(campo.getFieldEl()).find('.controllo-contestuale-errore');
        if (erroreDiv.length === 0) {
            erroreDiv = $('<div class="controllo-contestuale-errore"></div>');
            $(campo.getFieldEl()).append(erroreDiv);
        }
        erroreDiv.hide().empty();

        var campoSplitArray = campo.name.split("_");
        var jsonPathCampo = "$.['";
        for (var i = 0; i < campoSplitArray.length; i++) {
            if (i + 1 === campoSplitArray.length) {
                jsonPathCampo += campoSplitArray[i] + "']";
            } else {
                jsonPathCampo += campoSplitArray[i] + "']['";
            }
        }

        if (typeof curJQ !== 'undefined' && curJQ.blockUI) {
            curJQ.blockUI({
                message: "<div style='padding:20px 0; color: #ae1d3f; background-color: #FFF; opacity: 1 !important'>Attendere...</div>",
                baseZ: 2000,
                css: { border: 'none', fontFamily: "'Titillium Web',sans-serif", opacity: 0.7, color: '#ae1d3f' },
                overlayCSS: { backgroundColor: 'black', opacity: 0.6, cursor: 'wait' }
            });
        }

        var formData = form.getValue();
        var target = formData;
        for (var i = 0; i < campoSplitArray.length - 1; i++) {
            if (!target[campoSplitArray[i]]) {
                target[campoSplitArray[i]] = {};
            }
            target = target[campoSplitArray[i]];
        }
        target[campoSplitArray[campoSplitArray.length - 1]] = value;
        var dataForm = JSON.stringify({ alpaca: { data: formData } });

        $.ajax({
            url: verificaRequisitoContestualeUrl,
            dataType: 'json',
            timeout: 20000,
            data: { 'dataForm': dataForm, 'jsonPathCampo': jsonPathCampo },
            async: false,
            method: 'POST',
            error: function() {
                console.error("Errore validazione controllo contestuale numerico");
            },
            success: function(data) {
                if (data.status && data.status === "KO") {
                    if (data.errori) {
                        for (var i = 0; i < data.errori.length; i++) {
                            var message = "";
                            if (data.errori[i].obbligatorio) {
                                isControlloContestualeValid = false;
                                message += templateErrore.replace("%errorMessage%", data.errori[i].messaggio);
                            } else {
                                isControlloContestualeValid = true;
                                message += templateWarning.replace("%errorMessage%", data.errori[i].messaggio);
                            }
                            erroreDiv.html(message).show();
                        }
                    }
                } else {
                    isControlloContestualeValid = true;
                }
                form.refreshValidationState();
            },
            complete: function() {
                if (typeof curJQ !== 'undefined' && curJQ.unblockUI) {
                    curJQ.unblockUI();
                }
            }
        });
    }

    Alpaca.Fields.ControlloContestualeNumerico = Alpaca.Fields.ObjectField.extend(
    /**
     * @lends Alpaca.Fields.ControlloContestualeNumerico.prototype
     */
    {
        /**
         * @see Alpaca.Fields.ObjectField#getFieldType
         */
        getFieldType: function() {
            return "controlloContestualeNumerico";
        },

        /**
         * @private
         * @see Alpaca.Fields.ObjectField#setup
         */
        setup: function() {
            this.base();

            this.schema = {
                "type": "object",
                "properties": {
                    "valoreNumerico": {
                        "type": "string",
                        "pattern": "^([0-9]+)?$",
                        "properties": {}
                    }
                }
            };

            Alpaca.merge(this.options, {
                "validator": function(callback) {
                    if (!isControlloContestualeValid) {
                        callback({ "status": false });
                    } else {
                        callback({ "status": true });
                    }
                },
                "fields": {
                    "valoreNumerico": {
                        "type": "text",
                        "validate": true,
                        "showMessages": true,
                        "order": 1,
                        "helpers": [],
                        "hideInitValidationError": true,
                        "focus": false,
                        "disabled": false,
                        "readonly": false,
                        "renderButtons": true,
                        "data": {},
                        "attributes": {},
                        "allowOptionalEmpty": false,
                        "autocomplete": false,
                        "disallowEmptySpaces": false,
                        "disallowOnlyEmptySpaces": false,
                        "fields": {},
                        "events": {
                            "ready": function() {
                                var val = this.getValue();
                                if (val && val !== "") {
                                    validaControlloContestuale(this, val);
                                }
                            },
                            "change": function() {
                                validaControlloContestuale(this, this.getValue());
                            }
                        }
                    }
                },
                "view": "controlloContestualeNumerico-view"
            });
        },

        /**
         * @see Alpaca.Fields.ObjectField#getTitle
         */
        getTitle: function() {
            return "Controllo Contestuale Numerico";
        },

        /**
         * @see Alpaca.Fields.ObjectField#getDescription
         */
        getDescription: function() {
            return "Custom field con input numerico intero e validazione contestuale";
        }
    });

    Alpaca.registerView({
        "id": "controlloContestualeNumerico-view",
        "parent": "bootstrap-edit",
        "messages": {
            "notOptional": "Campo obbligatorio",
            "invalidPattern": "Inserire solo numeri interi"
        },
        "templates": {
            "container": controlloContestualeNumericoContainer,
            "container-object": controlloContestualeNumericoContainerObject
        }
    });

    Alpaca.registerFieldClass("controlloContestualeNumerico", Alpaca.Fields.ControlloContestualeNumerico);

})(jQuery);

