576	                    "aTotale":      creaOpzioniImporto(5, { disabled: true }),
577	                    "bTotale":      creaOpzioniImporto(6, { disabled: true }),
578	                    "totaleTotale": creaOpzioniImporto(7, { disabled: true })
579	                },
580	                "view": "riepilogoPerPartner-view"
581	            });
582	        },
583	
584	        getTitle: function() {
585	            return "Riepilogo Per Partner";
586	        },
587	
588	        getDescription: function() {
589	            return "Custom field tabellare di sola lettura: riepilogo costi per partner. " +
590	                   "Colonne: A.1/A.2/A.3/A(Costi diretti personale)/B(Altri costi)/TOTALE. " +
591	                   "Righe dinamiche (una per partner) + riga TOTALE finale.";
592	        },
593	
594	        // =================================================================
595	        // costruisciTabella() — popola le label dinamiche (denominazione)
596	        // nella prima colonna di ogni riga, con retry per DOM non pronto.
597	        // =================================================================
598	
599	        costruisciTabella: function() {
600	            var self = this;
601	            var campoElenco = self.childrenByPropertyId['elenco'];
602	            if (!campoElenco) return;
603	
604	            // Verifica che children esistano E che il DOM sia pronto
605	            var domPronto = campoElenco.children && campoElenco.children.length > 0;
606	            if (domPronto) {
607	                var firstItemEl = $(campoElenco.children[0].getFieldEl());
608	                domPronto = firstItemEl.find('.riepilogo-partner-label-dinamica').length > 0;
609	            }
610	
611	            if (!domPronto) {
612	                var retryCount = self._costruisciTabellaRetry || 0;
613	                if (retryCount < 15) {
614	                    self._costruisciTabellaRetry = retryCount + 1;
615	                    setTimeout(function() { self.costruisciTabella(); }, 300);
616	                }
617	                return;
618	            }
619	            self._costruisciTabellaRetry = 0;
620	
621	            // Leggi i valori dall'array tramite getValue() (NON childrenByPropertyId sui figli hidden)
622	            var valori = campoElenco.getValue();
623	
624	            for (var i = 0; i < campoElenco.children.length; i++) {
625	                var denominazione = (valori && valori[i]) ? (valori[i].denominazione || '') : '';
626	                $(campoElenco.children[i].getFieldEl())
627	                    .find('.riepilogo-partner-label-dinamica')
628	                    .text(denominazione);
629	            }
630	        },
631	
632	        // =================================================================
633	        // popolaRiepilogo() — metodo pubblico chiamato da TabellaPartner
634	        //                     dopo il calcolo AJAX.
635	        //
636	        // @param {Array}  partners         - Array allineato per indice ai partner.
637	        //   Ogni elemento: { denominazione, pIva, a1, a2, a3, b, totale }
638	        //   dove a1/a2/a3/b/totale sono stringhe formato IT ("10.100,28").
639	        //   La colonna A di ogni riga viene calcolata client-side = a1+a2+a3.
640	        //
641	        // @param {Object} totaliPerColonna - { a1, a2, a3, b, totale }
642	        //   per la riga TOTALE (formato IT).
643	        //
644	        // @param {string} totaleA         - Valore colonna A della riga TOTALE
645	        //   (formato IT, = riepilogoEvoluto.totaleA).
646	        //
647	        // No-op safe se partners è vuoto/null o i campi non esistono.
648	        // =================================================================
649	
650	        popolaRiepilogo: function(partners, totaliPerColonna, totaleA) {
651	            var self = this;
652	            if (!partners || !partners.length) return;
653	
654	            var campoElenco = self.childrenByPropertyId['elenco'];
655	            if (!campoElenco) return;
656	
657	            // --- Costruisce il valore dell'array elenco (denominazione + pIva) ---
658	            // e imposta il campo array (Alpaca ricrea i children)
659	            var nuovoElenco = [];
660	            for (var i = 0; i < partners.length; i++) {
661	                var p = partners[i];
662	                nuovoElenco.push({
663	                    denominazione: p.denominazione || '',
664	                    pIva: p.pIva || '',
665	                    a1: '',
666	                    a2: '',
667	                    a3: '',
668	                    a: '',
669	                    b: '',
670	                    totale: ''
671	                });
672	            }
673	            campoElenco.setValue(nuovoElenco);
674	
675	            // --- Valorizza i campi currency dei partner ---
676	            // Dopo setValue l'array viene ricreato; usiamo un retry per attendere
677	            // che i children siano di nuovo disponibili.
678	            function valorizzaPartners(attempt) {
679	                attempt = attempt || 0;
680	                var children = campoElenco.children;
681	                if (!children || children.length < partners.length) {
682	                    if (attempt < 20) {
683	                        setTimeout(function() { valorizzaPartners(attempt + 1); }, 300);
684	                    }
685	                    return;
686	                }
687	
688	                for (var j = 0; j < partners.length; j++) {
689	                    var p = partners[j];
690	                    var props = children[j].childrenByPropertyId;
691	                    if (!props) continue;
692	
693	                    // Colonna A = a1 + a2 + a3 (calcolata client-side)
694	                    var valA1 = parseImportoValue(p.a1);
695	                    var valA2 = parseImportoValue(p.a2);
696	                    var valA3 = parseImportoValue(p.a3);
697	                    var valA  = valA1 + valA2 + valA3;
698	
699	                    if (p.a1 !== undefined) setImportoFieldFromServer(props['a1'], p.a1);
700	                    if (p.a2 !== undefined) setImportoFieldFromServer(props['a2'], p.a2);
701	                    if (p.a3 !== undefined) setImportoFieldFromServer(props['a3'], p.a3);
702	                    setImportoField(props['a'], valA);
703	                    if (p.b !== undefined)  setImportoFieldFromServer(props['b'], p.b);
704	                    if (p.totale !== undefined) setImportoFieldFromServer(props['totale'], p.totale);
705	                }
706	
707	                // Riga TOTALE (campi top-level)
708	                if (totaliPerColonna) {
709	                    if (totaliPerColonna.a1 !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['a1Totale'], totaliPerColonna.a1);
710	                    if (totaliPerColonna.a2 !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['a2Totale'], totaliPerColonna.a2);
711	                    if (totaliPerColonna.a3 !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['a3Totale'], totaliPerColonna.a3);
712	                    if (totaliPerColonna.b  !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['bTotale'],  totaliPerColonna.b);
713	                    if (totaliPerColonna.totale !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['totaleTotale'], totaliPerColonna.totale);
714	                }
715	                if (totaleA !== undefined && totaleA !== null) {
716	                    setImportoFieldFromServer(self.childrenByPropertyId['aTotale'], totaleA);
717	                }
718	
719	                // Popola le label dinamiche dopo aver settato i dati
720	                self._costruisciTabellaRetry = 0;
721	                self.costruisciTabella();
722	
723	                // Triggera i controlli contestuali su bTotale e totaleTotale
724	                // (possono dipendere dai valori appena calcolati)
725	                triggerControlliContestuali(self);
726	            }
727	
728	            valorizzaPartners(0);
729	        },
730	
731	        // =================================================================
732	        // svuotaRiepilogo() — svuota tutti i campi (chiamato da modificaTabella)
733	        // =================================================================
734	
735	        svuotaRiepilogo: function() {
736	            var self = this;
737	            var campoElenco = self.childrenByPropertyId['elenco'];
738	            if (campoElenco && campoElenco.children) {
739	                for (var i = 0; i < campoElenco.children.length; i++) {
740	                    var props = campoElenco.children[i].childrenByPropertyId;
741	                    var colonne = ['a1', 'a2', 'a3', 'a', 'b', 'totale'];
742	                    for (var c = 0; c < colonne.length; c++) {
743	                        if (props[colonne[c]]) {
744	                            props[colonne[c]].setValue('');
745	                            var el = $(props[colonne[c]].getControlEl());
746	                            if (el.length && el.priceFormat) el.priceFormat(props[colonne[c]].options);
747	                        }
748	                    }
749	                }
750	            }
751	            var totali = ['a1Totale', 'a2Totale', 'a3Totale', 'aTotale', 'bTotale', 'totaleTotale'];
752	            for (var t = 0; t < totali.length; t++) {
753	                var campo = self.childrenByPropertyId[totali[t]];
754	                if (campo) {
755	                    campo.setValue('');
756	                    var elT = $(campo.getControlEl());
757	                    if (elT.length && elT.priceFormat) elT.priceFormat(campo.options);
758	                }
759	            }
760	        }
761	    });
