var riepilogoPerPartnerContainer = ' \
<script type="text/x-handlebars-template"> \
    <div data-custom-field="true" data-custom-field-height="400"> \
        {{#container}}{{/container}} \
    </div> \
</script>';

var riepilogoPerPartnerContainerObject = ' \
<script type="text/x-handlebars-template"> \
    <style> \
        .riepilogo-partner-wrapper .riepilogo-partner-elenco-array, .riepilogo-partner-elenco-array .alpaca-container, .riepilogo-partner-elenco-array .alpaca-container-item, .riepilogo-partner-elenco-array .alpaca-container-item > .alpaca-field { margin:0!important; padding:0!important; border:none!important; } \
        .riepilogo-partner-elenco-array > label.alpaca-control-label, .riepilogo-partner-elenco-array > .alpaca-control-label { display:none!important; } \
        .riepilogo-partner-wrapper table td .alpaca-field { margin-bottom:0!important; } \
        .riepilogo-partner-wrapper table td .form-group { margin-bottom:0!important; } \
        .riepilogo-partner-wrapper table td p.form-control-static:empty { display:none!important; } \
        .riepilogo-partner-wrapper table td label.alpaca-control-label:empty, .riepilogo-partner-wrapper table td label.control-label:empty { display:none!important; } \
        .riepilogo-partner-wrapper table td .form-control-static { min-height:0!important; padding-top:2px!important; padding-bottom:2px!important; } \
        .riepilogo-partner-item-table.table-bordered { border:1px solid #dee2e6!important; } \
        .riepilogo-partner-item-table, .riepilogo-partner-totale-row { table-layout:fixed!important; } \
        .riepilogo-partner-totale-row { border-top:none!important; } \
        .riepilogo-partner-totale-row td { border-top:none!important; } \
        .riepilogo-partner-elenco-array .alpaca-container-item + .alpaca-container-item .riepilogo-partner-item-table thead { display:none!important; } \
        .riepilogo-partner-elenco-array .alpaca-container-item + .alpaca-container-item .riepilogo-partner-item-table { margin-top:-1px!important; } \
    </style> \
    <div class="riepilogo-partner-wrapper" data-disable-interaction-custom-field="true"> \
        {{#with items.[0]}}{{#item}}{{/item}}{{/with}} \
        <table class="table table-bordered riepilogo-partner-totale-row mt-0 mb-0"> \
            <colgroup> \
                <col style="width:22%"> \
                <col style="width:13%"> \
                <col style="width:13%"> \
                <col style="width:13%"> \
                <col style="width:13%"> \
                <col style="width:13%"> \
                <col style="width:13%"> \
            </colgroup> \
            <tbody> \
                <tr style="font-weight:bold; background-color:#f8f9fa"> \
                    <td style="text-align:right; font-weight:bold; vertical-align:middle">TOTALE</td> \
                    <td style="font-weight:bold">{{#with items.[1]}}{{#item}}{{/item}}{{/with}}</td> \
                    <td style="font-weight:bold">{{#with items.[2]}}{{#item}}{{/item}}{{/with}}</td> \
                    <td style="font-weight:bold">{{#with items.[3]}}{{#item}}{{/item}}{{/with}}</td> \
                    <td style="font-weight:bold">{{#with items.[4]}}{{#item}}{{/item}}{{/with}}</td> \
                    <td style="font-weight:bold">{{#with items.[5]}}{{#item}}{{/item}}{{/with}}</td> \
                    <td style="font-weight:bold">{{#with items.[6]}}{{#item}}{{/item}}{{/with}}</td> \
                </tr> \
            </tbody> \
        </table> \
    </div> \
</script>';

/**
 * Custom Field Alpaca: RiepilogoPerPartner
 *
 * Tabella di SOLA LETTURA con riepilogo dei costi per partner.
 * Layout a 7 colonne: (etichetta partner) | A.1 | A.2 | A.3 | A | B | TOTALE.
 *
 * - Numero righe DINAMICO: un item dell'array `elenco` = un partner.
 * - Prima colonna di ogni riga = denominazione partner (label dinamica via retry).
 * - Riga TOTALE finale = campi top-level disabled.
 * - Tutti i campi currency sono disabled (sola lettura).
 *
 * Popolamento: chiamare il metodo pubblico `popolaRiepilogo(partners, totaliPerColonna, totaleA)`
 * da TabellaPartner dopo il calcolo AJAX.
 *
 * Firma popolaRiepilogo:
 *   @param {Array}  partners         - Array allineato per indice all'elenco partner.
 *                                      Ogni elemento: { denominazione, pIva, a1, a2, a3, b, totale }
 *                                      dove a1/a2/a3/b/totale sono stringhe formato IT ("10.100,28").
 *   @param {Object} totaliPerColonna - { a1, a2, a3, b, totale } per la riga TOTALE (formato IT).
 *   @param {string} totaleA          - Valore colonna A della riga TOTALE (formato IT).
 */
(function($) {

    var Alpaca = $.alpaca;

    // =====================================================================
    // Template messaggi controllo contestuale
    // =====================================================================
    var templateErroreContestuale = "<p style='color:red;'><i class='glyphicon glyphicon-exclamation-sign'></i>&nbsp;%errorMessage%</p>";
    var templateWarningContestuale = "<p style='color:#737373;'><i class='glyphicon glyphicon-exclamation-sign'></i>&nbsp;%errorMessage%</p>";

    // =====================================================================
    // blockUI / unblockUI con fallback
    // =====================================================================
    function doBlockUI() {
        if (typeof curJQ !== 'undefined' && curJQ.blockUI) {
            curJQ.blockUI({
                message: "<div style='padding:20px 0; color: #ae1d3f; background-color: #FFF; opacity: 1 !important'>Attendere...</div>",
                baseZ: 2000,
                css: {
                    border: 'none',
                    fontFamily: "'Titillium Web',sans-serif",
                    opacity: 0.7,
                    color: '#ae1d3f'
                },
                overlayCSS: {
                    backgroundColor: 'black',
                    opacity: 0.6,
                    cursor: 'wait'
                }
            });
        }
    }

    function doUnblockUI() {
        if (typeof curJQ !== 'undefined' && curJQ.unblockUI) {
            curJQ.unblockUI();
        }
    }

    // =====================================================================
    // validaContestuale — controllo BE generico su un campo del form.
    //   campo:        Alpaca field oggetto della validazione
    //   value:        valore corrente del campo (passato a parte per supportare bozze/calcoli)
    //   classeErrore: classe CSS univoca del div d'errore iniettato sotto il campo
    //   setFlag:      callback function(boolean) per aggiornare il flag di validità
    // =====================================================================
    function validaContestuale(campo, value, classeErrore, setFlag) {
        if (typeof verificaRequisitoContestualeUrl === 'undefined' || !verificaRequisitoContestualeUrl) return;

        var form = $('.alpaca-form').alpaca('get');
        var erroreDiv = $(campo.getFieldEl()).find('.' + classeErrore);
        if (erroreDiv.length === 0) {
            erroreDiv = $('<div class="' + classeErrore + '"></div>');
            $(campo.getFieldEl()).append(erroreDiv);
        }
        erroreDiv.hide().empty();

        var campoSplitArray = campo.name.split("_");
        var jsonPathCampo = "$.['";
        for (var i = 0; i < campoSplitArray.length; i++) {
            if (i + 1 === campoSplitArray.length) {
                jsonPathCampo += campoSplitArray[i] + "']";
            } else {
                jsonPathCampo += campoSplitArray[i] + "']['";
            }
        }

        doBlockUI();

        var formData = form.getValue();
        var target = formData;
        for (var i = 0; i < campoSplitArray.length - 1; i++) {
            if (!target[campoSplitArray[i]]) {
                target[campoSplitArray[i]] = {};
            }
            target = target[campoSplitArray[i]];
        }
        target[campoSplitArray[campoSplitArray.length - 1]] = value;
        var dataForm = JSON.stringify({ alpaca: { data: formData } });

        $.ajax({
            url: verificaRequisitoContestualeUrl,
            dataType: 'json',
            timeout: 20000,
            data: { 'dataForm': dataForm, 'jsonPathCampo': jsonPathCampo },
            async: false,
            method: 'POST',
            error: function() {
                console.error("RiepilogoPerPartner: errore validazione contestuale " + campo.name);
            },
            success: function(data) {
                if (data.status && data.status === "KO" && data.errori && data.errori.length > 0) {
                    var messaggi = "";
                    var hasBlocking = false;
                    for (var i = 0; i < data.errori.length; i++) {
                        var template = data.errori[i].obbligatorio
                            ? templateErroreContestuale
                            : templateWarningContestuale;
                        if (data.errori[i].obbligatorio) {
                            hasBlocking = true;
                        }
                        messaggi += template.replace("%errorMessage%", data.errori[i].messaggio);
                    }
                    setFlag(!hasBlocking);
                    erroreDiv.html(messaggi).show();
                } else {
                    setFlag(true);
                }
                form.refreshValidationState();
            },
            complete: function() {
                doUnblockUI();
            }
        });
    }

    // =====================================================================
    // triggerControlliContestuali(self) — triggera i controlli contestuali
    // su bTotale e totaleTotale. Da chiamare dopo ogni Calcola e al rientro
    // da bozza se i campi risultano già valorizzati.
    // =====================================================================
    function triggerControlliContestuali(self) {
        var bTotaleField = self.childrenByPropertyId['bTotale'];
        if (bTotaleField) {
            validaContestuale(
                bTotaleField,
                bTotaleField.getValue(),
                'btotale-contestuale-errore',
                function(v) { self._isBTotaleValid = v; }
            );
        }

        var totaleTotaleField = self.childrenByPropertyId['totaleTotale'];
        if (totaleTotaleField) {
            validaContestuale(
                totaleTotaleField,
                totaleTotaleField.getValue(),
                'totaletotale-contestuale-errore',
                function(v) { self._isTotaleTotaleValid = v; }
            );
        }
    }

    // =====================================================================
    // Utility currency (identiche a TabellaPartner.js)
    // =====================================================================

    function importoReadyHandler() {
        var rawData = this.data;
        var el = $(this.getControlEl());

        var originalGetVal = this.getValue;
        var fieldRef = this;
        this.getValue = function() {
            var val = originalGetVal.call(fieldRef);
            if (val == null || val === "") return val;
            var clean = String(val).replace(/[€\s]/g, '');
            if (clean.indexOf(',') !== -1) {
                clean = clean.replace(/\./g, '').replace(',', '.');
            }
            return clean;
        };

        if (rawData == null || rawData === "" || rawData === "NaN" || (typeof rawData === 'object')) {
            this.setValue("");
            el.priceFormat(this.options);
            return;
        }

        var strData = String(rawData).trim();
        if (strData === "" || strData === "NaN") {
            this.setValue("");
            el.priceFormat(this.options);
            return;
        }

        var cleanData = strData.replace(/[€\s]/g, '');
        if (cleanData.indexOf(',') !== -1) {
            cleanData = cleanData.replace(/\./g, '').replace(',', '.');
        }

        var numVal = parseFloat(cleanData);
        if (!isNaN(numVal)) {
            this.setValue(numVal.toFixed(2));
        } else {
            this.setValue("");
        }

        el.priceFormat(this.options);
    }

    function parseImportoValue(valore) {
        if (valore == null || valore === "") return 0;
        var clean = String(valore).replace(/[€\s]/g, '');
        if (clean.indexOf(',') !== -1) {
            clean = clean.replace(/\./g, '').replace(',', '.');
        }
        var num = parseFloat(clean);
        return isNaN(num) ? 0 : num;
    }

    function setImportoField(field, value) {
        if (!field) return;
        field.setValue(value.toFixed(2));
        var el = $(field.getControlEl());
        if (el.length && el.priceFormat) {
            el.priceFormat(field.options);
        }
    }

    function setImportoFieldFromServer(field, italianValue) {
        if (!field) return;
        var clean = String(italianValue).replace(/\./g, '').replace(',', '.');
        var numVal = parseFloat(clean);
        if (isNaN(numVal)) numVal = 0;
        field.setValue(numVal.toFixed(2));
        var el = $(field.getControlEl());
        if (el.length && el.priceFormat) {
            el.priceFormat(field.options);
        }
    }

    function creaOpzioniImporto(order, extraOpts) {
        extraOpts = extraOpts || {};
        return {
            "type": "text",
            "label": "",
            "order": order,
            "centsLimit": 2,
            "centsSeparator": ",",
            "prefix": "€",
            "round": "none",
            "thousandsSeparator": ".",
            "unmask": true,
            "disabled": extraOpts.disabled !== undefined ? extraOpts.disabled : true,
            "hidden": false,
            "helpers": [],
            "hideInitValidationError": true,
            "focus": false,
            "readonly": false,
            "renderButtons": true,
            "events": {
                "ready": importoReadyHandler
            },
            "validate": true,
            "showMessages": true,
            "data": {},
            "attributes": {},
            "allowOptionalEmpty": true,
            "autocomplete": false,
            "disallowEmptySpaces": false,
            "disallowOnlyEmptySpaces": false,
            "fieldClass": "importoFieldRight",
            "fields": {}
        };
    }

    // =====================================================================
    // Header colonne (HTML reso nel <thead>)
    // =====================================================================

    var COL_HEADERS = [
        'A.1<br>Spese per personale subordinato',
        'A.2<br>Spese per personale parasubordinato',
        'A.3<br>Impegno dell\'imprenditore agricolo',
        'A<br>Costi diretti del personale',
        'B.<br>Altri costi dell\'operazione',
        'TOTALE'
    ];

    // =====================================================================
    // buildArrayItemTemplate() — template dell'item (un partner = una riga)
    // =====================================================================

    function buildArrayItemTemplate() {
        // Ordine campi nell'item (items.[N]):
        // 0=denominazione, 1=pIva, 2=a1, 3=a2, 4=a3, 5=a, 6=b, 7=totale
        var html = "";

        html += "<table class='table table-bordered mb-0 riepilogo-partner-item-table'>" +
            "<colgroup>" +
                "<col style='width:22%'>" +
