                    "<th style='vertical-align:middle'></th>";

        for (var h = 0; h < COL_HEADERS.length; h++) {
            html += "<th style='text-align:center; font-size:0.85em'>" + COL_HEADERS[h] + "</th>";
        }

        html += "</tr>" +
            "</thead>" +
            "<tbody>" +
                "<tr>" +
                    "<td class='riepilogo-partner-label-dinamica align-middle' style='font-weight:bold'></td>" +
                    "<td>{{#with items.[2]}}{{#item}}{{/item}}{{/with}}</td>" +
                    "<td>{{#with items.[3]}}{{#item}}{{/item}}{{/with}}</td>" +
                    "<td>{{#with items.[4]}}{{#item}}{{/item}}{{/with}}</td>" +
                    "<td>{{#with items.[5]}}{{#item}}{{/item}}{{/with}}</td>" +
                    "<td>{{#with items.[6]}}{{#item}}{{/item}}{{/with}}</td>" +
                    "<td>{{#with items.[7]}}{{#item}}{{/item}}{{/with}}</td>" +
                "</tr>" +
            "</tbody>" +
        "</table>" +
        "<div style='display:none'>" +
            "{{#with items.[0]}}{{#item}}{{/item}}{{/with}}" +
            "{{#with items.[1]}}{{#item}}{{/item}}{{/with}}" +
        "</div>";

        return html;
    }

    var arrayItemContainerObject = buildArrayItemTemplate();

    // =====================================================================
    // buildItemSchema() — schema.properties per gli item dell'array
    // =====================================================================

    function buildItemSchema() {
        return {
            "denominazione": { "type": "string", "required": false, "properties": {} },
            "pIva":          { "type": "string", "required": false, "properties": {} },
            "a1":            { "type": "string", "required": false, "properties": {} },
            "a2":            { "type": "string", "required": false, "properties": {} },
            "a3":            { "type": "string", "required": false, "properties": {} },
            "a":             { "type": "string", "required": false, "properties": {} },
            "b":             { "type": "string", "required": false, "properties": {} },
            "totale":        { "type": "string", "required": false, "properties": {} }
        };
    }

    // =====================================================================
    // buildItemOptions() — options.fields per gli item dell'array
    // =====================================================================

    function buildItemOptions() {
        var fields = {};
        var order = 1;

        // denominazione (display, serve per label dinamica prima colonna)
        fields["denominazione"] = {
            "type": "text",
            "label": "",
            "order": order++,
            "hidden": false,
            "disabled": false,
            "helpers": [],
            "validate": false,
            "showMessages": false,
            "renderButtons": true,
            "view": "bootstrap-display",
            "data": {},
            "attributes": {},
            "allowOptionalEmpty": true,
            "autocomplete": false,
            "disallowEmptySpaces": false,
            "disallowOnlyEmptySpaces": false,
            "fields": {}
        };

        // pIva (hidden, persistenza)
        fields["pIva"] = {
            "type": "text",
            "label": "P. IVA",
            "order": order++,
            "hidden": true,
            "validate": false,
            "showMessages": false,
            "renderButtons": true,
            "data": {},
            "attributes": {},
            "allowOptionalEmpty": true,
            "autocomplete": false,
            "disallowEmptySpaces": false,
            "disallowOnlyEmptySpaces": false,
            "fields": {}
        };

        // Colonne currency (tutti disabled = sola lettura)
        // Ordine: a1(order3), a2(order4), a3(order5), a(order6), b(order7), totale(order8)
        // → items.[2]..items.[7] nel template
        fields["a1"]     = creaOpzioniImporto(order++, { disabled: true });
        fields["a2"]     = creaOpzioniImporto(order++, { disabled: true });
        fields["a3"]     = creaOpzioniImporto(order++, { disabled: true });
        fields["a"]      = creaOpzioniImporto(order++, { disabled: true });
        fields["b"]      = creaOpzioniImporto(order++, { disabled: true });
        fields["totale"] = creaOpzioniImporto(order++, { disabled: true });

        return fields;
    }

    // =====================================================================
    // Alpaca Field Class
    // =====================================================================

    Alpaca.Fields.RiepilogoPerPartner = Alpaca.Fields.ObjectField.extend(
    /** @lends Alpaca.Fields.RiepilogoPerPartner.prototype */
    {
        getFieldType: function() {
            return "riepilogoPerPartner";
        },

        setup: function() {
            this.base();

            this.schema = {
                "type": "object",
                "properties": {
                    "elenco": {
                        "type": "array",
                        "required": false,
                        "items": {
                            "type": "object",
                            "properties": buildItemSchema()
                        },
                        "properties": {}
                    },
                    // Riga TOTALE finale (campi top-level)
                    "a1Totale":     { "type": "string", "required": false, "properties": {} },
                    "a2Totale":     { "type": "string", "required": false, "properties": {} },
                    "a3Totale":     { "type": "string", "required": false, "properties": {} },
                    "aTotale":      { "type": "string", "required": false, "properties": {} },
                    "bTotale":      { "type": "string", "required": false, "properties": {} },
                    "totaleTotale": { "type": "string", "required": false, "properties": {} }
                }
            };

            var self = this;

            // Flag validazione contestuale PER ISTANZA (evita leak tra istanze)
            self._isBTotaleValid = true;
            self._isTotaleTotaleValid = true;

            Alpaca.merge(this.options, {
                "label": "",
                "validator": function(callback) {
                    callback({ "status": (self._isBTotaleValid !== false) && (self._isTotaleTotaleValid !== false) });
                },
                "events": {
                    "ready": function() {
                        var selfReady = this;
                        setTimeout(function() {
                            selfReady.costruisciTabella();

                            // Rientro da bozza: triggera i controlli contestuali
                            // solo se almeno uno dei due campi è già valorizzato.
                            var bTotaleField = selfReady.childrenByPropertyId['bTotale'];
                            var totaleTotaleField = selfReady.childrenByPropertyId['totaleTotale'];
                            var bTotaleVal = bTotaleField ? String(bTotaleField.getValue() || '').trim() : '';
                            var totaleTotaleVal = totaleTotaleField ? String(totaleTotaleField.getValue() || '').trim() : '';
                            if (bTotaleVal !== '' || totaleTotaleVal !== '') {
                                triggerControlliContestuali(selfReady);
                            }
                        }, 200);
                    }
                },
                "fields": {
                    "elenco": {
                        "type": "array",
                        "label": "",
                        "fieldClass": "riepilogo-partner-elenco-array formatArrayExport",
                        "validate": false,
                        "disabled": false,
                        "hideToolbar": true,
                        "hideActionbar": true,
                        "toolbarSticky": false,
                        "showMoveUpItemButton": false,
                        "showMoveDownItemButton": false,
                        "hidden": false,
                        "toolbarStyle": "none",
                        "actionbarStyle": "none",
                        "items": {
                            "showMoveUpItemButton": false,
                            "showMoveDownItemButton": false,
                            "view": {
                                "templates": {
                                    "container": "<div class='border-0 p-0 m-0'>{{#container}}{{/container}}</div>",
                                    "container-object": arrayItemContainerObject
                                },
                                "messages": {
                                    "notOptional": "Campo obbligatorio"
                                },
                                "parent": "bootstrap-edit"
                            },
                            "fields": buildItemOptions()
                        },
                        "rubyrails": false,
                        "order": 1,
                        "fields": {}
                    },
                    // Riga TOTALE finale — campi top-level disabled, order 2..7
                    // Vengono renderizzati nella <table> riepilogo del container-object
                    // (items.[1]..items.[6] nel template principale)
                    "a1Totale":     creaOpzioniImporto(2, { disabled: true }),
                    "a2Totale":     creaOpzioniImporto(3, { disabled: true }),
                    "a3Totale":     creaOpzioniImporto(4, { disabled: true }),
                    "aTotale":      creaOpzioniImporto(5, { disabled: true }),
                    "bTotale":      creaOpzioniImporto(6, { disabled: true }),
                    "totaleTotale": creaOpzioniImporto(7, { disabled: true })
                },
                "view": "riepilogoPerPartner-view"
            });
        },

        getTitle: function() {
            return "Riepilogo Per Partner";
        },

        getDescription: function() {
            return "Custom field tabellare di sola lettura: riepilogo costi per partner. " +
                   "Colonne: A.1/A.2/A.3/A(Costi diretti personale)/B(Altri costi)/TOTALE. " +
                   "Righe dinamiche (una per partner) + riga TOTALE finale.";
        },

        // =================================================================
        // costruisciTabella() — popola le label dinamiche (denominazione)
        // nella prima colonna di ogni riga, con retry per DOM non pronto.
        // =================================================================

        costruisciTabella: function() {
            var self = this;
            var campoElenco = self.childrenByPropertyId['elenco'];
            if (!campoElenco) return;

            // Verifica che children esistano E che il DOM sia pronto
            var domPronto = campoElenco.children && campoElenco.children.length > 0;
            if (domPronto) {
                var firstItemEl = $(campoElenco.children[0].getFieldEl());
                domPronto = firstItemEl.find('.riepilogo-partner-label-dinamica').length > 0;
            }

            if (!domPronto) {
                var retryCount = self._costruisciTabellaRetry || 0;
                if (retryCount < 15) {
                    self._costruisciTabellaRetry = retryCount + 1;
                    setTimeout(function() { self.costruisciTabella(); }, 300);
                }
                return;
            }
            self._costruisciTabellaRetry = 0;

            // Leggi i valori dall'array tramite getValue() (NON childrenByPropertyId sui figli hidden)
            var valori = campoElenco.getValue();

            for (var i = 0; i < campoElenco.children.length; i++) {
                var denominazione = (valori && valori[i]) ? (valori[i].denominazione || '') : '';
                $(campoElenco.children[i].getFieldEl())
                    .find('.riepilogo-partner-label-dinamica')
                    .text(denominazione);
            }
        },

        // =================================================================
        // popolaRiepilogo() — metodo pubblico chiamato da TabellaPartner
        //                     dopo il calcolo AJAX.
        //
        // @param {Array}  partners         - Array allineato per indice ai partner.
        //   Ogni elemento: { denominazione, pIva, a1, a2, a3, b, totale }
        //   dove a1/a2/a3/b/totale sono stringhe formato IT ("10.100,28").
        //   La colonna A di ogni riga viene calcolata client-side = a1+a2+a3.
        //
        // @param {Object} totaliPerColonna - { a1, a2, a3, b, totale }
        //   per la riga TOTALE (formato IT).
        //
        // @param {string} totaleA         - Valore colonna A della riga TOTALE
        //   (formato IT, = riepilogoEvoluto.totaleA).
        //
        // No-op safe se partners è vuoto/null o i campi non esistono.
        // =================================================================

        popolaRiepilogo: function(partners, totaliPerColonna, totaleA) {
            var self = this;
            if (!partners || !partners.length) return;

            var campoElenco = self.childrenByPropertyId['elenco'];
            if (!campoElenco) return;

            // --- Costruisce il valore dell'array elenco (denominazione + pIva) ---
            // e imposta il campo array (Alpaca ricrea i children)
            var nuovoElenco = [];
            for (var i = 0; i < partners.length; i++) {
                var p = partners[i];
                nuovoElenco.push({
                    denominazione: p.denominazione || '',
                    pIva: p.pIva || '',
                    a1: '',
                    a2: '',
                    a3: '',
                    a: '',
                    b: '',
                    totale: ''
                });
            }
            campoElenco.setValue(nuovoElenco);

            // --- Valorizza i campi currency dei partner ---
            // Dopo setValue l'array viene ricreato; usiamo un retry per attendere
            // che i children siano di nuovo disponibili.
            function valorizzaPartners(attempt) {
                attempt = attempt || 0;
                var children = campoElenco.children;
                if (!children || children.length < partners.length) {
                    if (attempt < 20) {
                        setTimeout(function() { valorizzaPartners(attempt + 1); }, 300);
                    }
                    return;
                }

                for (var j = 0; j < partners.length; j++) {
                    var p = partners[j];
                    var props = children[j].childrenByPropertyId;
                    if (!props) continue;

                    // Colonna A = a1 + a2 + a3 (calcolata client-side)
                    var valA1 = parseImportoValue(p.a1);
                    var valA2 = parseImportoValue(p.a2);
                    var valA3 = parseImportoValue(p.a3);
                    var valA  = valA1 + valA2 + valA3;

                    if (p.a1 !== undefined) setImportoFieldFromServer(props['a1'], p.a1);
                    if (p.a2 !== undefined) setImportoFieldFromServer(props['a2'], p.a2);
                    if (p.a3 !== undefined) setImportoFieldFromServer(props['a3'], p.a3);
                    setImportoField(props['a'], valA);
                    if (p.b !== undefined)  setImportoFieldFromServer(props['b'], p.b);
                    if (p.totale !== undefined) setImportoFieldFromServer(props['totale'], p.totale);
                }

                // Riga TOTALE (campi top-level)
                if (totaliPerColonna) {
                    if (totaliPerColonna.a1 !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['a1Totale'], totaliPerColonna.a1);
                    if (totaliPerColonna.a2 !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['a2Totale'], totaliPerColonna.a2);
                    if (totaliPerColonna.a3 !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['a3Totale'], totaliPerColonna.a3);
                    if (totaliPerColonna.b  !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['bTotale'],  totaliPerColonna.b);
                    if (totaliPerColonna.totale !== undefined) setImportoFieldFromServer(self.childrenByPropertyId['totaleTotale'], totaliPerColonna.totale);
                }
                if (totaleA !== undefined && totaleA !== null) {
                    setImportoFieldFromServer(self.childrenByPropertyId['aTotale'], totaleA);
                }

                // Popola le label dinamiche dopo aver settato i dati
                self._costruisciTabellaRetry = 0;
                self.costruisciTabella();

                // Triggera i controlli contestuali su bTotale e totaleTotale
                // (possono dipendere dai valori appena calcolati)
                triggerControlliContestuali(self);
            }

            valorizzaPartners(0);
        },

        // =================================================================
        // svuotaRiepilogo() — svuota tutti i campi (chiamato da modificaTabella)
        // =================================================================

        svuotaRiepilogo: function() {
            var self = this;
            var campoElenco = self.childrenByPropertyId['elenco'];
            if (campoElenco && campoElenco.children) {
                for (var i = 0; i < campoElenco.children.length; i++) {
                    var props = campoElenco.children[i].childrenByPropertyId;
                    var colonne = ['a1', 'a2', 'a3', 'a', 'b', 'totale'];
                    for (var c = 0; c < colonne.length; c++) {
                        if (props[colonne[c]]) {
                            props[colonne[c]].setValue('');
                            var el = $(props[colonne[c]].getControlEl());
                            if (el.length && el.priceFormat) el.priceFormat(props[colonne[c]].options);
                        }
                    }
                }
            }
            var totali = ['a1Totale', 'a2Totale', 'a3Totale', 'aTotale', 'bTotale', 'totaleTotale'];
            for (var t = 0; t < totali.length; t++) {
                var campo = self.childrenByPropertyId[totali[t]];
                if (campo) {
                    campo.setValue('');
                    var elT = $(campo.getControlEl());
                    if (elT.length && elT.priceFormat) elT.priceFormat(campo.options);
                }
            }
        }
    });

    Alpaca.registerView({
        "id": "riepilogoPerPartner-view",
        "parent": "bootstrap-edit",
        "messages": {
            "notOptional": "Campo obbligatorio"
        },
        "templates": {
            "container": riepilogoPerPartnerContainer,
            "container-object": riepilogoPerPartnerContainerObject
        }
    });

    Alpaca.registerFieldClass("riepilogoPerPartner", Alpaca.Fields.RiepilogoPerPartner);

})(jQuery);

