(function($) {

	var Alpaca = $.alpaca;

	var isImportoRichiestoValid = true;
	var templateErrore = "<p style='color:red;'><i class='glyphicon glyphicon-exclamation-sign'></i>&nbsp;%errorMessage%</p>";
	var templateWarning = "<p style='color:#737373;'><i class='glyphicon glyphicon-exclamation-sign'></i>&nbsp;%errorMessage%</p>";

	function validaImportoRichiesto (self, value) {
        if (verificaRequisitoContestualeUrl) {
            var form = $('.alpaca-form').alpaca('get');
            var errore = self.parent.childrenByPropertyId['errore'];

            errore.options.hidden = true;
            errore.refresh();
            //chiamata ajax
            var campoSplitArray = self.name.split("_");

            var campo = "$.['";

            for (var i=0; i<campoSplitArray.length; i++) {
                if (i+1 === campoSplitArray.length) {
                    campo+= campoSplitArray[i] + "']";
                } else {
                    campo+= campoSplitArray[i] + "']['";
                }
            }

            curJQ.blockUI({
                message : "<div style='padding:20px 0; color: #ae1d3f; background-color: #FFF; opacity: 1 !important'>Attendere...</div>",
                baseZ : 2000,
                css : {
                    border : 'none',
                    fontFamily : "'Titillium Web',sans-serif",
                    opacity : 0.7,
                    color : '#ae1d3f',
                },
                overlayCSS : {
                    backgroundColor : 'black',
                    opacity : 0.6,
                    cursor : 'wait'
                }
            });

            var formData = form.getValue();
            var target = formData;
            for (var i = 0; i < campoSplitArray.length - 1; i++) {
                if (!target[campoSplitArray[i]]) {
                    target[campoSplitArray[i]] = {};
                }
                target = target[campoSplitArray[i]];
            }
            target[campoSplitArray[campoSplitArray.length - 1]] = value;
            var dataForm = JSON.stringify({ alpaca: { data: formData } });
            $.ajax({
                url : verificaRequisitoContestualeUrl,
                dataType : 'json',
                timeout : 20000,
                data: {
                    'dataForm' : dataForm,
                    'jsonPathCampo' : campo
                },
                async : false,
                method : 'POST',
                error : function() {
                    console.log("error");
                },
                success : function(data) {
                    if (data.status && data.status === "KO") {
                        if (data.errori) {
                            var message = "";
                            isImportoRichiestoValid = true;
                            for (var i=0; i<data.errori.length; i++) {
                                if (data.errori[i].obbligatorio) {
                                    isImportoRichiestoValid = false;
                                    message += templateErrore.replace("%errorMessage%", data.errori[i].messaggio);
                                } else {
                                    message += templateWarning.replace("%errorMessage%", data.errori[i].messaggio);
                                }
                            }
                            errore.options.label = message;
                            errore.options.hidden = false;
                            errore.refresh();
                        }
                    } else {
                        isImportoRichiestoValid = true;
                    }
                    form.refreshValidationState();
                },
                complete: function() {
                    self.parent.refreshValidationState();
                    curJQ.unblockUI();
                }
            });
        }
	}

	var countDecimals = function (value) {

	    if (Math.floor(value) === value) return 0;

	    var str = value.toString();
	    if (str.indexOf(".") !== -1 && str.indexOf("-") !== -1) {
	        return str.split("-")[1] || 0;
	    } else if (str.indexOf(".") !== -1) {
	        return str.split(".")[1].length || 0;
	    }
	    return str.split("-")[1] || 0;
	}

	Alpaca.Fields.ImportoRichiesto = Alpaca.Fields.ObjectField
			.extend(
			/**
			 * @lends Alpaca.Fields.ImportoRichiesto.prototype
			 */
			{
				/**
				 * @see Alpaca.Fields.ObjectField#getFieldType
				 */
				getFieldType : function() {
					return "importoRichiesto";
				},

				/**
				 * @private
				 * @see Alpaca.Fields.ObjectField#setup
				 */
				setup : function() {
					this.base();

					this.schema = {
						"type" : "object",
						"properties" : {
							"importo" : {
								"type" : "string",
								"required" : true, 	
								"properties" : {}
							},
							"errore" : {
								"type" : "string",
								"required" : false,
								"properties" : {}
							}
						}
					};

					Alpaca.merge(this.options, {
						"label" : "",
                        "validator": function(callback) {

                            if (!isImportoRichiestoValid) {
                                callback({
                                    "status": false
                                });
                            } else {
                                callback({
                                    "status": true
                                });
                            }
                        },
						"fields" : {
							"importo" : {
			                    "type": "currency",
			                    "centsLimit": 2,
			                    "centsSeparator": ",",
			                    "prefix": "€",
			                    "round": "none",
			                    "thousandsSeparator": ".",
			                    "unmask": true,
			                    "disabled": false,
			                    "hidden": false,
			                    "helpers": [],
			                    "hideInitValidationError": true,
			                    "focus": false,
			                    "readonly": false,
			                    "renderButtons": true,
			                    "events": {},
			                    "order": 1,
			                    "validate": true,
			                    "showMessages": true,
			                    "data": {},
			                    "attributes": {},
			                    "allowOptionalEmpty": true,
			                    "autocomplete": false,
			                    "disallowEmptySpaces": false,
			                    "disallowOnlyEmptySpaces": false,
			                    "fieldClass": "importoFieldRight",
			                    "events": {
									"ready": function() {
										if(this.data && !isNaN(parseFloat(this.data))){
											var decimali = countDecimals(parseFloat(this.data));
											var importo;

											switch(decimali) {
												case 0 :
													importo = parseFloat(this.data).toFixed(2);
													break;
												case 1 :
													importo = parseFloat(this.data).toFixed(2);
													break;
												case 2 :
													importo = parseFloat(this.data);
													break;
												default: 
													break;
											}

											if (importo) {
												this.setValue(importo);
												$(this.getControlEl()).priceFormat(this.options);
                                                validaImportoRichiesto(this, importo);
											}
										}else{
											this.setValue("");
										}
									},
									"change": function() {
                                        validaImportoRichiesto(this, this.getValue());
									}
			                    },
			                    "fields": {}
			                },
                            "errore" : {
                                "validate" : true,
                                "showMessages" : true,
                                "fieldClass": "hideInExcelExport",
                                "type" : "text",
                                "hidden": true,
                                "order": 2,
                                "disabled" : true,
                                "renderButtons" : true,
                                "view": "bootstrap-display",
                                "attributes" : {},
                                "fields" : {}
                            }
						},
						"view" : "importoRichiesto-view"
					});

				},

				/**
				 * @see Alpaca.Fields.ObjectField#getTitle
				 */
				getTitle : function() {
					return "Campo Importo Richiesto Domanda Bando";
				},

				/**
				 * @see Alpaca.Fields.ObjectField#getDescription
				 */
				getDescription : function() {
					return "Campo che permette di inserire un importo, con le relative validazioni in fase di compilazione del campo.";
				}
			});

	Alpaca.registerView({
		"id" : "importoRichiesto-view",
		"parent" : "bootstrap-create",
		"messages" : {
			"notOptional" : "Campo obbligatorio.",
			"invalidPattern": "Inserire un valore numerico con max 2 cifre decimali."
		},
		"templates" : {
			"container" : importoRichiestoContainer,
			"container-object" : importoRichiestoContainerObject
		}
	});
	Alpaca.registerFieldClass("importoRichiesto", Alpaca.Fields.ImportoRichiesto);

})(jQuery);

