95		/**
96		 * Valida i dati di un form Alpaca rispetto ai requisiti configurati per un bando.
97		 * Esegue la validazione su ogni requisito definito, confrontando i valori inseriti nel form
98		 * con i valori attesi secondo gli operatori configurati. Supporta validazioni numeriche, testuali,
99		 * su date e booleani, oltre a operatori speciali come percentuali e condizioni IN.
100		 *
101		 * @param alpacaFormData la stringa JSON contenente i dati del form Alpaca da validare
102		 * @param bandoId l'ID del bando per cui effettuare la validazione
103		 * @param locale il locale da utilizzare per la generazione dei messaggi di errore localizzati
104		 * @param requisitoDomandaBandoLst la lista dei requisiti di validazione configurati per il bando
105		 * @return una lista di errori di validazione rilevati, vuota se la validazione ha successo
106		 */
107		@Override
108		public List<ErroreValidazioneDTO> validaForm(String alpacaFormData, long bandoId, Locale locale, List<RequisitoDomandaBando> requisitoDomandaBandoLst){
109			List<ErroreValidazioneDTO> listaErroriValidazione = new ArrayList<>();
110	
111			if(!Validator.isBlank(alpacaFormData) && bandoId > 0){
112				ErroreValidazioneDTO erroreValidazioneDTO = null;
113	//			configurazione JSONPath
114				Set<Option> jsonPathOptions = new HashSet<Option>();
115				jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS); //verra' titornato null in caso di PathNotFoundException
116				jsonPathOptions.add(Option.ALWAYS_RETURN_LIST); //verra' ritornato array vuoto in caso di nessun valore
117	
118				Configuration jsonPathConfiguration = Configuration.builder()
119						.jsonProvider(new JacksonJsonNodeJsonProvider())
120						.mappingProvider(new JacksonMappingProvider())
121						.options(jsonPathOptions)
122						.build();
123	
124				JsonNode fieldValues = null;
125				List<ValoreRequisitoDomanda> valoreRequisitoLst = null;
126				if(requisitoDomandaBandoLst != null){
127					for(RequisitoDomandaBando requisito : requisitoDomandaBandoLst){
128						
129						Operazione operazione = null;
130						
131						if(requisito.getOperazioneId()>0) {
132							operazione = operazioneLocalService.fetchOperazione(requisito.getOperazioneId());
133						}
134						String codiceRequisito = requisito.getCodiceRequisito();
135						
136						Boolean campoTestuale = isCampoTestuale(codiceRequisito,jsonPathConfiguration,alpacaFormData);
137						
138						valoreRequisitoLst = valoreRequisitoDomandaLocalService.getValoreRequisitoDomandaByRequisitoDomandaBandoId(requisito.getRequisitoDomandaBandoId());
139	
140						if(Validator.isNotNull(valoreRequisitoLst) && !valoreRequisitoLst.isEmpty()){
141	//						recupero il campo con l'opportuno codice dal json
142	
143							String fieldName = getFieldNameFromJsonPathPattern(requisito.getCodiceRequisito());
144							List<String> pathFieldFound = JsonPath.using(Configuration.builder().options(Option.AS_PATH_LIST).build()).parse(alpacaFormData).read("$.." + fieldName);
145							List<String> nomiPath = new ArrayList<String>();
146							nomiPath.add(ALPACA_ALPACA_FIELD);
147							nomiPath.add(ALPACA_DATA_FIELD);
148							
149							List<String> pathFound = filterPathByFieldList(pathFieldFound, nomiPath);
150							
151							if(pathFound!=null && !pathFound.isEmpty()) {
152								if (pathFound.size() > 1) {
153									//TODO ottimizzare gestione
154									//TODO concatenare alpaca data subito dopo il dollaro
155									String field = requisito.getCodiceRequisito().substring(requisito.getCodiceRequisito().indexOf(".") + 1);
156									String jsonPath = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD+ field;
157									
158									fieldValues = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(jsonPath);
159									
160								} else {
161									fieldValues = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(pathFound.get(0));
162								}
163								
164	
165								if(fieldValues != null){
166									for(JsonNode node : fieldValues){
167										if (operazione.getOperazione().equals(FormOperators.IN)) {
168											
169											//in caso di opeatore IN, vado a forzare il mostra valori (per evitare nullPointer nel buildErroreValidazioneDTO)
170											requisito.setMostraValoreCorretto(false);
171											erroreValidazioneDTO = validateFidelINCondition(alpacaFormData, valoreRequisitoLst, node, requisito, locale,campoTestuale);
172											if(Validator.isNotNull(erroreValidazioneDTO)) {
173												listaErroriValidazione.add(erroreValidazioneDTO);
174											}
175											
176										} else {						
177											if (valoreRequisitoLst.size() == 1) {
178												ValoreRequisitoDomanda valoreRequisito = valoreRequisitoLst.get(0);
179																																							
180												try{
181													if(isDecimalNumber(valoreRequisito.getValoreRequisitoDomanda()) && !campoTestuale){
182														erroreValidazioneDTO = validateNumber(alpacaFormData, valoreRequisito, node, requisito, locale);
183													} else if (Validator.isBoolean(valoreRequisito.getValoreRequisitoDomanda())){
184														erroreValidazioneDTO = validateBoolean(alpacaFormData, valoreRequisito, node, requisito, locale);
185													} else if(this.isDate(valoreRequisito.getValoreRequisitoDomanda())){
186														erroreValidazioneDTO = validateDate(alpacaFormData, valoreRequisito, node, requisito, locale);
187													}else{
188														erroreValidazioneDTO = validateString(alpacaFormData, valoreRequisito,node, requisito, locale);
189													}
190													if(Validator.isNotNull(erroreValidazioneDTO)){
191														listaErroriValidazione.add(erroreValidazioneDTO);
192													}
193												}catch (RuntimeException runtimeException){
194													log.error("Errore durante la validazione del form :: " + runtimeException.getMessage(), runtimeException);
195												}
196											}									
197										}
198									}
199								}
200							} else {
201								if (requisito.getTipologiaValidazione().equalsIgnoreCase(TipologiaValidazione.PREVALIDAZIONE.name())) {
202									ValoreRequisitoDomanda valoreRequisito = valoreRequisitoLst.get(0);
203									erroreValidazioneDTO = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, null, String.class);
204									if (operazione != null && operazione.getOperazione().equals(FormOperators.CONTAINS) && Validator.isNotNull(erroreValidazioneDTO)) {
205										String containsError = getErrorMessageByOperation(operazione.getOperazione(), locale, new String[]{ null, valoreRequisito.getValoreRequisitoDomanda() }, String.class);
206										if (Validator.isNotNull(containsError)) {
207											erroreValidazioneDTO.setDescrizione(containsError);
208										}
209									}
210									if(Validator.isNotNull(erroreValidazioneDTO)){
211										listaErroriValidazione.add(erroreValidazioneDTO);
212									}
213								}
214							}
215						}
216					}
217				}
218				
219			}
220			return listaErroriValidazione;
221		}
