223		private ErroreValidazioneDTO validateFidelINCondition(String alpacaFormData,
224				List<ValoreRequisitoDomanda> valoreRequisitoLst, JsonNode valoreNodo, RequisitoDomandaBando requisito,
225				Locale locale, Boolean campoTestuale) {
226	
227			ErroreValidazioneDTO error = null;
228			
229			if (campoTestuale) {
230				List<String> listaValori = new ArrayList<String>();
231				for (ValoreRequisitoDomanda valoreRequisito : valoreRequisitoLst) {
232					listaValori.add(valoreRequisito.getValoreRequisitoDomanda().trim());
233				}
234				if (!listaValori.contains(valoreNodo.asText().trim())) {
235					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisitoLst.get(0),valoreNodo.asText().trim(), String.class);
236				}
237			} else {
238				List<BigDecimal> listaValori = new ArrayList<BigDecimal>();
239				for (ValoreRequisitoDomanda valoreRequisito : valoreRequisitoLst) {
240					if (isDecimalNumber(valoreRequisito.getValoreRequisitoDomanda())){
241						listaValori.add( new BigDecimal(normalizeDecimalNumber(valoreRequisito.getValoreRequisitoDomanda())));
242					}
243				}
244				BigDecimal formNumber = null;
245				if (isDecimalNumber(valoreNodo.asText())){
246					formNumber = new BigDecimal(normalizeDecimalNumber(valoreNodo.asText()));
247					if (!listaValori.contains(formNumber)) {
248						error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisitoLst.get(0),valoreNodo.asText().trim(), String.class);
249					}
250				}
251			}
252			return error;
253		}
254	
255		private boolean isCampoTestuale(String codiceRequisito, Configuration jsonPathConfiguration, String alpacaFormData) {
256			if (!Validator.isNotNull(codiceRequisito)) {
257				return false;
258			}
259	
260			String pathCampo = codiceRequisito.substring(codiceRequisito.indexOf("["), codiceRequisito.indexOf("]") + 1);
261			String nomeCampo = codiceRequisito.substring(codiceRequisito.lastIndexOf("['") + 2, codiceRequisito.lastIndexOf("']"));
262	
263			JsonNode optionsFields = JsonPath.using(jsonPathConfiguration)
264					.parse(alpacaFormData)
265					.read(ALPACA_ALPACA_FIELD + ALPACA_OPTION_FIELD + ALPACA_FIELDS_FIELD + pathCampo + ALPACA_FIELDS_FIELD);
266	
267			if (optionsFields != null) {
