/**
 * Implementazione del servizio per la validazione delle domande di bando.
 * Esegue la validazione dei form Alpaca utilizzando requisiti configurabili, supportando
 * diversi tipi di dati (stringhe, numeri, date, booleani) e operatori di confronto.
 * Genera messaggi di errore localizzati con informazioni contestuali sui campi non validi.
 *
 * @author Servizi Digitali
 * @see it.servizidigitali.gestionebandi.common.service.ValidaDomandaBandoService
 */
@Component(name = "validaDomandaBandoService", immediate = true, service = ValidaDomandaBandoService.class)
public class ValidaDomandaBandoServiceImpl implements ValidaDomandaBandoService{

	private static final Log log = LogFactoryUtil.getLog(ValidaDomandaBandoServiceImpl.class.getName());

	private static final String ALPACA_FIELD_OPEN_PATTERN = "['";
	private static final String ALPACA_FIELD_CLOSING_PATTERN = "']";
	private static final String DATE_TIME_FORMATTER_PATTERN = "dd/MM/yyyy";
	private static final String ALPACA_OPTION_FIELD = "['options']";
	private static final String ALPACA_FIELDS_FIELD = "['fields']";
	private static final String ALPACA_ALPACA_FIELD = "$['alpaca']";
	private static final String ALPACA_DATA_FIELD = "['data']";
	private static final String ALPACA_VIEW_FIELD = "['view']";
	private static final String ALPACA_WIZARD_FIELD = "['wizard']";
	private static final String ALPACA_STEPS_FIELD = "['steps']";
	private static final String ALPACA_BINDINGS_FIELD = "['bindings']";
	private static final String ALPACA_LABEL_FIELD = "['label']";
	private static final String ALPACA_TITLE_FIELD = "['title']";
	private static final String ALPACA_DESCRIPTION_FIELD = "['description']";
	private static final String ALPACA_TYPE_FIELD = "['type']";
	private static final String ALPACA_REGEX_ESTRAZIONE_NODI = "\\['([^']*)'\\]";

	@Reference
	private RequisitoDomandaBandoLocalService requisitoDomandaBandoLocalService;

	@Reference
	private ValoreRequisitoDomandaLocalService valoreRequisitoDomandaLocalService;

	@Reference
	private OperazioneLocalService operazioneLocalService;

	/**
	 * Valida i dati di un form Alpaca rispetto ai requisiti configurati per un bando.
	 * Esegue la validazione su ogni requisito definito, confrontando i valori inseriti nel form
	 * con i valori attesi secondo gli operatori configurati. Supporta validazioni numeriche, testuali,
	 * su date e booleani, oltre a operatori speciali come percentuali e condizioni IN.
	 *
	 * @param alpacaFormData la stringa JSON contenente i dati del form Alpaca da validare
	 * @param bandoId l'ID del bando per cui effettuare la validazione
	 * @param locale il locale da utilizzare per la generazione dei messaggi di errore localizzati
	 * @param requisitoDomandaBandoLst la lista dei requisiti di validazione configurati per il bando
	 * @return una lista di errori di validazione rilevati, vuota se la validazione ha successo
	 */
	@Override
	public List<ErroreValidazioneDTO> validaForm(String alpacaFormData, long bandoId, Locale locale, List<RequisitoDomandaBando> requisitoDomandaBandoLst){
		List<ErroreValidazioneDTO> listaErroriValidazione = new ArrayList<>();

		if(!Validator.isBlank(alpacaFormData) && bandoId > 0){
			ErroreValidazioneDTO erroreValidazioneDTO = null;
//			configurazione JSONPath
			Set<Option> jsonPathOptions = new HashSet<Option>();
			jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS); //verra' titornato null in caso di PathNotFoundException
			jsonPathOptions.add(Option.ALWAYS_RETURN_LIST); //verra' ritornato array vuoto in caso di nessun valore

			Configuration jsonPathConfiguration = Configuration.builder()
					.jsonProvider(new JacksonJsonNodeJsonProvider())
					.mappingProvider(new JacksonMappingProvider())
					.options(jsonPathOptions)
					.build();

			JsonNode fieldValues = null;
			List<ValoreRequisitoDomanda> valoreRequisitoLst = null;
			if(requisitoDomandaBandoLst != null){
				for(RequisitoDomandaBando requisito : requisitoDomandaBandoLst){

					Operazione operazione = null;

					if(requisito.getOperazioneId()>0) {
						operazione = operazioneLocalService.fetchOperazione(requisito.getOperazioneId());
					}
					String codiceRequisito = requisito.getCodiceRequisito();

					Boolean campoTestuale = isCampoTestuale(codiceRequisito,jsonPathConfiguration,alpacaFormData);

					valoreRequisitoLst = valoreRequisitoDomandaLocalService.getValoreRequisitoDomandaByRequisitoDomandaBandoId(requisito.getRequisitoDomandaBandoId());

					if(Validator.isNotNull(valoreRequisitoLst) && !valoreRequisitoLst.isEmpty()){
//						recupero il campo con l'opportuno codice dal json

						String fieldName = getFieldNameFromJsonPathPattern(requisito.getCodiceRequisito());
						List<String> pathFieldFound = JsonPath.using(Configuration.builder().options(Option.AS_PATH_LIST).build()).parse(alpacaFormData).read("$.." + fieldName);
						List<String> nomiPath = new ArrayList<String>();
						nomiPath.add(ALPACA_ALPACA_FIELD);
						nomiPath.add(ALPACA_DATA_FIELD);

						List<String> pathFound = filterPathByFieldList(pathFieldFound, nomiPath);

						if(pathFound!=null && !pathFound.isEmpty()) {
							if (pathFound.size() > 1) {
								//TODO ottimizzare gestione
								//TODO concatenare alpaca data subito dopo il dollaro
								String field = requisito.getCodiceRequisito().substring(requisito.getCodiceRequisito().indexOf(".") + 1);
								String jsonPath = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD+ field;

								fieldValues = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(jsonPath);

							} else {
								fieldValues = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(pathFound.get(0));
							}


							if(fieldValues != null){
								for(JsonNode node : fieldValues){
									if (operazione.getOperazione().equals(FormOperators.IN)) {

										//in caso di opeatore IN, vado a forzare il mostra valori (per evitare nullPointer nel buildErroreValidazioneDTO)
										requisito.setMostraValoreCorretto(false);
										erroreValidazioneDTO = validateFidelINCondition(alpacaFormData, valoreRequisitoLst, node, requisito, locale,campoTestuale);
										if(Validator.isNotNull(erroreValidazioneDTO)) {
											listaErroriValidazione.add(erroreValidazioneDTO);
										}

									} else {						
										if (valoreRequisitoLst.size() == 1) {
											ValoreRequisitoDomanda valoreRequisito = valoreRequisitoLst.get(0);

											try{
												if(isDecimalNumber(valoreRequisito.getValoreRequisitoDomanda()) && !campoTestuale){
													erroreValidazioneDTO = validateNumber(alpacaFormData, valoreRequisito, node, requisito, locale);
												} else if (Validator.isBoolean(valoreRequisito.getValoreRequisitoDomanda())){
													erroreValidazioneDTO = validateBoolean(alpacaFormData, valoreRequisito, node, requisito, locale);
												} else if(this.isDate(valoreRequisito.getValoreRequisitoDomanda())){
													erroreValidazioneDTO = validateDate(alpacaFormData, valoreRequisito, node, requisito, locale);
												}else{
													erroreValidazioneDTO = validateString(alpacaFormData, valoreRequisito,node, requisito, locale);
												}
												if(Validator.isNotNull(erroreValidazioneDTO)){
													listaErroriValidazione.add(erroreValidazioneDTO);
												}
											}catch (RuntimeException runtimeException){
												log.error("Errore durante la validazione del form :: " + runtimeException.getMessage(), runtimeException);
											}
										}									
									}
								}
							}
						} else {
							if (requisito.getTipologiaValidazione().equalsIgnoreCase(TipologiaValidazione.PREVALIDAZIONE.name())) {
								ValoreRequisitoDomanda valoreRequisito = valoreRequisitoLst.get(0);
								erroreValidazioneDTO = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, null, String.class);
								if (operazione != null && operazione.getOperazione().equals(FormOperators.CONTAINS) && Validator.isNotNull(erroreValidazioneDTO)) {
									String containsError = getErrorMessageByOperation(operazione.getOperazione(), locale, new String[]{ null, valoreRequisito.getValoreRequisitoDomanda() }, String.class);
									if (Validator.isNotNull(containsError)) {
										erroreValidazioneDTO.setDescrizione(containsError);
									}
								}
								if(Validator.isNotNull(erroreValidazioneDTO)){
									listaErroriValidazione.add(erroreValidazioneDTO);
								}
							}
						}
					}
				}
			}

		}
		return listaErroriValidazione;
	}

	private ErroreValidazioneDTO validateFidelINCondition(String alpacaFormData,
			List<ValoreRequisitoDomanda> valoreRequisitoLst, JsonNode valoreNodo, RequisitoDomandaBando requisito,
			Locale locale, Boolean campoTestuale) {

		ErroreValidazioneDTO error = null;

		if (campoTestuale) {
			List<String> listaValori = new ArrayList<String>();
			for (ValoreRequisitoDomanda valoreRequisito : valoreRequisitoLst) {
				listaValori.add(valoreRequisito.getValoreRequisitoDomanda().trim());
			}
			if (!listaValori.contains(valoreNodo.asText().trim())) {
				error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisitoLst.get(0),valoreNodo.asText().trim(), String.class);
			}
		} else {
			List<BigDecimal> listaValori = new ArrayList<BigDecimal>();
			for (ValoreRequisitoDomanda valoreRequisito : valoreRequisitoLst) {
				if (isDecimalNumber(valoreRequisito.getValoreRequisitoDomanda())){
					listaValori.add( new BigDecimal(normalizeDecimalNumber(valoreRequisito.getValoreRequisitoDomanda())));
				}
			}
			BigDecimal formNumber = null;
			if (isDecimalNumber(valoreNodo.asText())){
				formNumber = new BigDecimal(normalizeDecimalNumber(valoreNodo.asText()));
				if (!listaValori.contains(formNumber)) {
					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisitoLst.get(0),valoreNodo.asText().trim(), String.class);
				}
			}
		}
		return error;
	}

	private boolean isCampoTestuale(String codiceRequisito, Configuration jsonPathConfiguration, String alpacaFormData) {
		if (!Validator.isNotNull(codiceRequisito)) {
			return false;
		}

		String pathCampo = codiceRequisito.substring(codiceRequisito.indexOf("["), codiceRequisito.indexOf("]") + 1);
		String nomeCampo = codiceRequisito.substring(codiceRequisito.lastIndexOf("['") + 2, codiceRequisito.lastIndexOf("']"));

		JsonNode optionsFields = JsonPath.using(jsonPathConfiguration)
				.parse(alpacaFormData)
				.read(ALPACA_ALPACA_FIELD + ALPACA_OPTION_FIELD + ALPACA_FIELDS_FIELD + pathCampo + ALPACA_FIELDS_FIELD);

		if (optionsFields != null) {
			JsonNode fields = optionsFields.get(0);

			if(fields!=null && fields.has(nomeCampo) && fields.get(nomeCampo)!=null){
				JsonNode fieldsCampo = fields.get(nomeCampo);
                return !fieldsCampo.isObject()
                        || !fieldsCampo.has("numerico") || !fieldsCampo.get("numerico").asBoolean(false);
            }

		}

		String jsonPath = getPathTypeFromCodiceRequisito(codiceRequisito);
		JsonNode jsonNodes = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(jsonPath);

		if (Validator.isNotNull(jsonNodes) && Validator.isNotNull(jsonNodes.get(0))) {
			String type = jsonNodes.get(0).asText();
			if ("text".equalsIgnoreCase(type) || "textarea".equalsIgnoreCase(type)) {
				return true;
			}
		}

		return false;
	}

	private String getCodiceRequisito(long requisitoDomandaBandoId, List<RequisitoDomandaBando> requisitoDomandaBandoLst) {		
	    return requisitoDomandaBandoLst.stream()
	        .filter(r -> r.getRequisitoDomandaBandoId() == requisitoDomandaBandoId)
	        .map(RequisitoDomandaBando::getCodiceRequisito)
	        .findFirst()
	        .orElse(null);
	}

	private ErroreValidazioneDTO validateString(String alpacaFormData, ValoreRequisitoDomanda valoreRequisito, JsonNode valoreNodo, RequisitoDomandaBando requisito, Locale locale) throws FormValidationException{
		ErroreValidazioneDTO error = null;
		Operazione operazione = null;

		if(requisito.getOperazioneId()>0) {
			operazione = operazioneLocalService.fetchOperazione(requisito.getOperazioneId());
		}

		switch (operazione.getOperazione()){
			case FormOperators.EQ:
				if(!(valoreRequisito.getValoreRequisitoDomanda().trim().equalsIgnoreCase(valoreNodo.asText().trim()))){
					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
				}
				break;

			case FormOperators.NE:
				if((valoreRequisito.getValoreRequisitoDomanda().trim().equalsIgnoreCase(valoreNodo.asText().trim()))){
					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
				}
				break;

			case FormOperators.NN:
				if (Validator.isNull(valoreNodo.asText().trim())) {
					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
				}
				break;

			case FormOperators.CONTAINS:
				if (!valoreNodo.asText().trim().toUpperCase().contains(valoreRequisito.getValoreRequisitoDomanda().trim().toUpperCase())) {
					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
				}
				break;

			default:
				throw new RuntimeException("operatore non supportato RequisitoDomandaBando id :: " + requisito.getRequisitoDomandaBandoId());
		}
		return error;
	}

	private String getPathTypeFromCodiceRequisito(String codiceRequisito) {
        StringBuilder outJsonPat = new StringBuilder();
        outJsonPat.append(ALPACA_ALPACA_FIELD + ALPACA_OPTION_FIELD + ALPACA_FIELDS_FIELD);
        Pattern pattern = Pattern.compile(ALPACA_REGEX_ESTRAZIONE_NODI);
        Matcher matcher = pattern.matcher(codiceRequisito);

        List<String> nodi = new ArrayList<>();
        while (matcher.find()) {
            nodi.add(matcher.group(1));
        }

        if (!nodi.isEmpty()) {
